 function restoreLocation(initial=false){
  restoring=true;routeNotice='';route=new URLSearchParams(location.search);let normalize=false,hash='';try{hash=decodeURIComponent(location.hash.slice(1));}catch{}
  // A recognized legacy hash is an explicit navigation command, before query details.
  if(hash.startsWith('node=')){route.set('node',hash.slice(5));route.delete('catalog');normalize=true;}else if(viewIDs.includes(hash)){route.set('view',hash);route.delete('node');route.delete('catalog');normalize=true;}else if(location.hash&&hash!=='main'){routeNotice='未知或无法解析的页面锚点；请选择导航入口。';}
  // Conflicting query details select catalog deterministically, including an empty/unknown ID.
  if(route.has('catalog')&&route.has('node')){route.delete('node');normalize=true;}
  if(route.has('view')&&!viewIDs.includes(route.get('view'))){route.set('view','explore');routeNotice='未知视图，已返回探索知识；未替换任何实体身份。';normalize=true;}
  if(!route.has('view'))route.set('view',route.has('catalog')?'vendor-catalog':'explore');
  for(const id of filterIDs)$(id).value=route.get(id)||'';
  refreshLists();
  if(route.has('catalog')){if(catalogController)catalogController.select(route.get('catalog'),false,'none');else $('catalog-detail').replaceChildren(el('h3','目录模块不可用'),el('p','请返回结果，检查同一发布版本的脚本与数据。'));}
  else if(route.has('node')){if(nodes.has(route.get('node')))choose(route.get('node'),false,'none');else {selected=null;$('detail').replaceChildren(el('h3','未知知识 ID'),el('p','未自动替换为其他实体。请返回结果重新查找。'));$('graph').replaceChildren();$('relations').replaceChildren();for(const b of $('results').querySelectorAll('button'))b.setAttribute('aria-current','false');}}
  reveal();if(route.has('catalog')||route.has('node'))detailTOC($(route.has('catalog')?'catalog-detail':'detail'));
  restoring=false;if(normalize)commit('replace');
  if(!initial){const pos=positions.get(routeURL());window.scrollTo?.(0,pos?.y||0);}
 }
 restoreLocation(true);
